type PageRow = {
    Id: string
    Name: string
    Title: string
    Teaser: string
    Body: string
    CreatedAt: int
    UpdatedAt: int option
    DeletedAt: int option
}

type PageCreate = {
    Name: string
    Title: string
    Teaser: string
    Body: string
}

let parsePageRow (row: obj) : PageRow =
    { Id = rowStr row "id"
      Name = rowStr row "name"
      Title = rowStr row "title"
      Teaser = rowStr row "teaser"
      Body = rowStr row "body"
      CreatedAt = rowInt row "created_at"
      UpdatedAt = rowIntOpt row "updated_at"
      DeletedAt = rowIntOpt row "deleted_at" }

let selectPages (db: D1Database) : D1PreparedStatement =
    db.prepare("SELECT id, name, title, teaser, body, created_at, updated_at, deleted_at FROM pages WHERE deleted_at IS NULL ORDER BY created_at DESC LIMIT 100")

let selectPage (id: string) (db: D1Database) : D1PreparedStatement =
    bind (db.prepare("SELECT id, name, title, teaser, body, created_at, updated_at, deleted_at FROM pages WHERE id = ? AND deleted_at IS NULL")) [| box id |]

let insertPage (db: D1Database) (create: PageCreate) =
    let id = newId()
    let now = epochNow()
    let stmt =
        bind (db.prepare("INSERT INTO pages (id, name, title, teaser, body, created_at) VALUES (?, ?, ?, ?, ?, ?)"))
             [| box id; box create.Name; box create.Title; box create.Teaser; box create.Body; box now |]
    {| Stmt = stmt; Id = id; CreatedAt = now |}

let updatePage (id: string) (create: PageCreate) (db: D1Database) : D1PreparedStatement =
    let now = epochNow()
    bind (db.prepare("UPDATE pages SET name = ?, title = ?, teaser = ?, body = ?, updated_at = ? WHERE id = ?"))
         [| box create.Name; box create.Title; box create.Teaser; box create.Body; box now; box id |]

let deletePage (id: string) (db: D1Database) : D1PreparedStatement =
    bind (db.prepare("UPDATE pages SET deleted_at = CAST(strftime('%s','now') AS INTEGER) WHERE id = ?")) [| box id |]

